func (this *Bitopro) ParseMarket(market any) any {
	var active any = (!IsEqual(this.SafeBool(market, "maintain"), true))
	var id any = this.SafeString(market, "pair")
	if IsTrue(IsEqual(id, nil)) {
		panic(ExchangeError(Add(this.Id, " parseMarket() missing id")))
	}
	var uppercaseId string = ToUpper(id)
	var baseId any = this.SafeString(market, "base")
	var quoteId any = this.SafeString(market, "quote")
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var symbol any = Add(Add(base, "/"), quote)
	var limits map[string]any = map[string]any{
		"amount": map[string]any{
			"min": this.SafeNumber(market, "minLimitBaseAmount"),
			"max": this.SafeNumber(market, "maxLimitBaseAmount"),
		},
		"price": map[string]any{
			"min": nil,
			"max": nil,
		},
		"cost": map[string]any{
			"min": nil,
			"max": nil,
		},
		"leverage": map[string]any{
			"min": nil,
			"max": nil,
		},
	}
	return this.SafeMarketStructure(map[string]any{
		"id":             id,
		"uppercaseId":    uppercaseId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"baseId":         base,
		"quoteId":        quote,
		"settle":         nil,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"limits":         limits,
		"precision": map[string]any{
			"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quotePrecision"))),
			"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "basePrecision"))),
		},
		"active":  active,
		"created": nil,
		"info":    market,
	})
}
func (this *Bitopro) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	//     {
	//         "pair":"btc_twd",
	//         "lastPrice":"1182449.00000000",
	//         "isBuyer":false,
	//         "priceChange24hr":"-1.99",
	//         "volume24hr":"9.13089740",
	//         "high24hr":"1226097.00000000",
	//         "low24hr":"1181000.00000000"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId any = this.SafeString(ticker, "pair")
	market = this.SafeMarket(marketId, market)
	var symbol any = this.SafeString(market, "symbol")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          this.SafeString(ticker, "high24hr"),
		"low":           this.SafeString(ticker, "low24hr"),
		"bid":           nil,
		"bidVolume":     nil,
		"ask":           nil,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         this.SafeString(ticker, "lastPrice"),
		"last":          this.SafeString(ticker, "lastPrice"),
		"previousClose": nil,
		"change":        nil,
		"percentage":    this.SafeString(ticker, "priceChange24hr"),
		"average":       nil,
		"baseVolume":    this.SafeString(ticker, "volume24hr"),
		"quoteVolume":   nil,
		"info":          ticker,
	}, market)
}

