func (this *Bitopro) ParseTransactionStatus(status any) any {
	var states map[string]any = map[string]any{
		"COMPLETE":           "ok",
		"INVALID":            "failed",
		"PROCESSING":         "pending",
		"WAIT_PROCESS":       "pending",
		"FAILED":             "failed",
		"EXPIRED":            "failed",
		"CANCELLED":          "failed",
		"EMAIL_VERIFICATION": "pending",
		"WAIT_CONFIRMATION":  "pending",
	}
	return this.SafeString(states, status, status)
}
func (this *Bitopro) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//    {
	//        "serial": "20220214X766799",
	//        "timestamp": "1644833015053",
	//        "address": "bnb1xml62k5a9dcewgc542fha75fyxdcp0zv8eqfsh",
	//        "amount": "0.20000000",
	//        "fee": "0.00000000",
	//        "total": "0.20000000",
	//        "status": "COMPLETE",
	//        "txid": "A3CC4F6828CC752B9F3737F48B5826B9EC2857040CB5141D0CC955F7E53DB6D9",
	//        "message": "778553959",
	//        "protocol": "MAIN",
	//        "id": "2905906537"
	//    }
	//
	// fetchWithdrawals || fetchWithdraw
	//
	//    {
	//        "serial": "20220215BW14069838",
	//        "timestamp": "1644907716044",
	//        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
	//        "amount": "8.00000000",
	//        "fee": "2.00000000",
	//        "total": "10.00000000",
	//        "status": "COMPLETE",
	//        "txid": "50bf250c71a582f40cf699fb58bab978437ea9bdf7259ff8072e669aab30c32b",
	//        "protocol": "TRX",
	//        "id": "9925310345"
	//    }
	//
	// withdraw
	//
	//    {
	//        "serial": "20220215BW14069838",
	//        "currency": "USDT",
	//        "protocol": "TRX",
	//        "address": "TKrwMaZaGiAvtXCFT41xHuusNcs4LPWS7w",
	//        "amount": "8",
	//        "fee": "2",
	//        "total": "10"
	//    }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId any = this.SafeString(transaction, "coin")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.SafeInteger(transaction, "timestamp")
	var address any = this.SafeString(transaction, "address")
	var tag any = this.SafeString(transaction, "message")
	var status any = this.SafeString(transaction, "status")
	var networkId any = this.SafeString(transaction, "protocol")
	if IsTrue(IsEqual(networkId, "MAIN")) {
		networkId = code
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "serial"),
		"txid":        this.SafeString(transaction, "txid"),
		"type":        nil,
		"currency":    code,
		"network":     this.NetworkIdToCode(networkId, code),
		"amount":      this.SafeNumber(transaction, "total"),
		"status":      this.ParseTransactionStatus(status),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber(transaction, "fee"),
			"rate":     nil,
		},
	}
}

