			AddElementToObject(headers, "X-BITOPRO-APIKEY", this.ApiKey)
			AddElementToObject(headers, "X-BITOPRO-PAYLOAD", payload)
			AddElementToObject(headers, "X-BITOPRO-SIGNATURE", signature)
